use vstd::prelude::*;

verus! {

fn reverse(a: &[i32]) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == a@[a@.len() - 1 - i],
{
    let mut result = Vec::with_capacity(a.len());

    for &x in a.iter().rev()
        invariant
            // The abstract length of `result` matches its concrete length
            result@.len() == result.len(),
            // `result` is never longer than the input
            result@.len() <= a@.len(),
            // `result` contains the reverse of the processed suffix of `a`
            forall|i: int|
                0 <= i < result@.len() ==>
                    result@[i] == a@[a@.len() - 1 - i],
    {
        result.push(x);

        // Helpful to maintain the link between concrete and spec views after mutation
        assert(result@.len() == result.len());
    }

    result
}

} // verus!